      "category": "concept"
    },
    {
      "name": "核",
      "aliases": ["kernel", "零空间"],
      "definition_snippet": "Ker(T) = {α ∈ V | T(α) = 0}。",
      "category": "concept"
    },
    {
      "name": "像",
      "aliases": ["image", "列空间"],
      "definition_snippet": "Im(T) = {T(α) | α ∈ V}。",
      "category": "concept"
    },
    {
      "name": "维数",
      "aliases": ["dimension", "维数 dim"],
      "definition_snippet": "向量空间或子空间的基所含向量个数。",
      "category": "concept"
    },
    {
      "name": "秩-零度定理",
      "aliases": ["rank-nullity theorem", "秩零度定理"],
      "definition_snippet": "dim(Ker(T)) + dim(Im(T)) = dim(V)。",
      "category": "theorem"
    },
    {
      "name": "线性变换的复合",
      "aliases": ["composition of linear transformations", "复合变换"],
      "definition_snippet": "若 T: U → V，S: V → W，则 S∘T: U → W。",
      "category": "operation"
    },
    {
      "name": "可逆线性变换",
      "aliases": ["invertible linear transformation", "可逆线性映射"],
      "definition_snippet": "存在逆变换的线性变换。",
      "category": "concept"
    },
    {
      "name": "逆线性变换",
      "aliases": ["inverse linear transformation", "逆变换"],
      "definition_snippet": "若 T 可逆，则 T⁻¹ 也是线性变换。",
      "category": "operation"
    },
    {
      "name": "矩阵乘法",
      "aliases": ["matrix multiplication", "矩阵相乘"],
      "definition_snippet": "线性变换复合对应的矩阵运算。",
      "category": "operation"
    },
    {
      "name": "特征值",
      "aliases": ["eigenvalue", "特征值 λ"],
      "definition_snippet": "线性变换本身的固有性质，不依赖于基的选择。",
      "category": "concept"
